root = Path(__file__).resolve().parents[1]
by_file = {}
records = []
for i, (category, question, answer, context, filename) in enumerate(items, 1):
    by_file.setdefault(filename, set()).add(context)
    records.append({"id": f"qa_{i:03d}", "category": category, "question": question,
                    "reference_answer": answer, "context": context, "difficulty": "easy" if i % 3 else "medium",
                    "relevant_chunk_id": f"{filename}:0"})
(root / "datasets" / "golden_dataset.jsonl").write_text(
    "\n".join(json.dumps(row, ensure_ascii=False) for row in records) + "\n", encoding="utf-8")
for filename, paragraphs in by_file.items():
    (root / "datasets" / "sample_documents" / filename).write_text("\n\n".join(sorted(paragraphs)), encoding="utf-8")
print(f"Wrote {len(records)} records across {len(by_file)} Persian documents")
